<?php
declare(strict_types=1);
require_once __DIR__.'/StaySchema.php';
require_once __DIR__.'/Media.php';
final class Stays
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public function list():array{$out=[];foreach($this->query('SELECT id,slug,data,version,updated_at FROM jingo_stays ORDER BY updated_at DESC,id')->fetchAll(PDO::FETCH_ASSOC) as $r)$out[]=array_replace(json_decode($r['data'],true,512,JSON_THROW_ON_ERROR),['id'=>$r['id'],'slug'=>$r['slug'],'version'=>(int)$r['version'],'updatedAt'=>$r['updated_at']]);return $out;}
    public function save(array $input,string $actor):array
    {
        $p=StaySchema::property($input);$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$old=$this->query('SELECT slug,data,version FROM jingo_stays WHERE id=? FOR UPDATE',[$p['id']])->fetch(PDO::FETCH_ASSOC);if(($old?(int)$old['version']:0)!==$p['version'])throw new HttpError(409,'Cơ sở vừa thay đổi. Tải lại trước khi lưu.');$images=[...($p['coverId'] ?? null?[$p['coverId']]:[]),...$p['galleryIds'],...array_column($p['rooms'],'imageId')];(new Media($this->db,''))->validateIds($images);$en=$p['slugEn']?:$p['slug'];foreach($this->query('SELECT id,slug,data FROM jingo_stays')->fetchAll(PDO::FETCH_ASSOC) as $r)if($r['id']!==$p['id']){$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if($r['slug']===$p['slug']||(($d['slugEn'] ?? '')?:$r['slug'])===$en)throw new HttpError(409,'Đường dẫn lưu trú đã được sử dụng.');}foreach(['vi'=>$p['slug'],'en'=>$en] as $lang=>$slug){$owner=$this->query('SELECT hotel_id FROM jingo_stay_aliases WHERE lang=? AND slug=?',[$lang,$slug])->fetchColumn();if($owner!==false&&$owner!==$p['id'])throw new HttpError(409,'Đường dẫn cũ thuộc cơ sở khác.');}
            $this->query("UPDATE jingo_stay_bookings SET status='EXPIRED',version=version+1 WHERE hotel_id=? AND status='PENDING' AND expires_at<=UTC_TIMESTAMP(6) AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.paymentStatus'))='UNPAID'",[$p['id']]);$usage=[];foreach($this->query("SELECT room_id,check_in,check_out,rooms FROM jingo_stay_bookings WHERE hotel_id=? AND status NOT IN ('CANCELLED','EXPIRED','COMPLETED')",[$p['id']])->fetchAll(PDO::FETCH_ASSOC) as $b){$i=array_search($b['room_id'],array_column($p['rooms'],'id'),true);if($i===false)throw new HttpError(409,'Loại phòng còn đơn đang xử lý, không thể xóa. Hãy tắt mở bán.');$start=new DateTimeImmutable(StaySchema::date($b['check_in']),new DateTimeZone('UTC'));$end=new DateTimeImmutable(StaySchema::date($b['check_out']),new DateTimeZone('UTC'));$n=(int)$start->diff($end)->format('%r%a');if($n<1||$n>30)throw new HttpError(409,'Khoảng đêm của đơn phòng không hợp lệ.');for($day=0;$day<$n;$day++){$date=$start->modify('+'.$day.' days')->format('Y-m-d');$key=$i.':'.$date;$usage[$key]=($usage[$key] ?? 0)+(int)$b['rooms'];}}foreach($usage as $key=>$count){[$i,$date]=explode(':',$key,2);$r=$p['rooms'][(int)$i];if(isset($r['saleFrom'])&&$date<$r['saleFrom']||isset($r['saleTo'])&&$date>$r['saleTo'])continue;if(StaySchema::stock($r,$date)<$count)throw new HttpError(409,'Tồn đêm '.$date.' thấp hơn '.$count.' phòng đã giữ.');}
            $version=$p['version']+1;unset($p['version']);$json=json_encode($p,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if($old)$this->query('UPDATE jingo_stays SET slug=?,data=?,version=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$p['slug'],$json,$version,$p['id']]);else $this->query('INSERT INTO jingo_stays(id,slug,data,version) VALUES (?,?,?,?)',[$p['id'],$p['slug'],$json,$version]);if($old){$d=json_decode($old['data'],true,512,JSON_THROW_ON_ERROR);foreach(['vi'=>[$old['slug'],$p['slug']],'en'=>[($d['slugEn'] ?? '')?:$old['slug'],$en]] as $lang=>[$before,$after])if($before!==$after)$this->query('INSERT INTO jingo_stay_aliases(lang,slug,hotel_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE hotel_id=hotel_id',[$lang,$before,$p['id']]);}$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'stay.property.save',$p['id']]);$p['updatedAt']=$this->query('SELECT updated_at FROM jingo_stays WHERE id=?',[$p['id']])->fetchColumn();$this->db->commit();$p['version']=$version;return $p;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof PDOException&&$e->getCode()==='23000')throw new HttpError(409,'Đường dẫn cơ sở bị trùng.');throw $e;}
    }
}
